export const genres=['Indie','Pop','Hip hop','Elettronica','R&B'];
export const catalog=Array.from({length:25},(_,i)=>({id:`t${i}`,artist:['Luna Bassa','Fuori Orario','Nove','Iride','Sottovoce','Marea','Nina Sera','Kairo','Altrove','Solea','Milo','Cobalto','Zero Nord','Etere','Amì','Vela','Luce Fredda','Nadir','Prisma','Dalia','Nubi','Elia Blu','Rayo','Mono','Naima'][i],title:['Vetro blu','Non dormire','Orbita','A luci spente','Restiamo qui','Altri giorni','Satelliti','Cemento','Distanze','Piano piano','Domenica','Senza rumore','Sette piani','Supernova','Fino a te','Fuori stagione','Città vuota','Verticale','Onde corte','Le cose piccole','Piove ancora','Quasi estate','Polvere','Notte elettrica','Tra le righe'][i],genre:genres[i%5],mood:['Notturno','Energico','Sognante','Euforico','Intimo'][i%5],lang:i%3?'Italiano':'Inglese',listeners:820+i*271,exposures:240+i*37,votes:28+(i*19)%115,audio:`audio/${i%5}.wav`}));
export function rome(now=new Date()){const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(now).map(p=>[p.type,p.value]));return{day:`${p.year}-${p.month}-${p.day}`,seconds:+p.hour*3600 + +p.minute*60 + +p.second,revealed:+p.hour>=21};}
export function rng(seed){let s=2166136261;for(const c of seed)s=Math.imul(s^c.charCodeAt(0),16777619);return()=>{s+=0x6D2B79F5;let t=Math.imul(s^s>>>15,1|s);t^=t+Math.imul(t^t>>>7,61|t);return((t^t>>>14)>>>0)/4294967296;};}
export function selectTracks(pool,prefs,seed){const random=rng(seed);const compatible=pool.filter(t=>t.listeners<10000&&prefs.includes(t.genre));const ranked=compatible.map(t=>({t,key:-Math.log(Math.max(random(),1e-9))*(t.exposures+1)})).sort((a,b)=>a.key-b.key);return ranked.slice(0,5).map(x=>x.t.id);}
export function score(votes,exposures){return exposures>0?votes/exposures:0;}
export function eligibility(n){return Number.isInteger(n)&&n>=0&&n<10000;}
export function canVote(round,revealed){return !revealed&&!round.vote&&round.ids.every(id=>round.listened.includes(id));}
export function rankRows(pool,period,day){return pool.map(t=>{const r=rng(t.id+day+period);let exposures=0,votes=0;for(let i=0;i<(period==='week'?7:1);i++){const e=100+Math.floor(r()*500);exposures+=e;votes+=Math.floor(e*(.07+r()*.3));}return{...t,exposures,votes,score:score(votes,exposures)};}).sort((a,b)=>b.score-a.score||b.exposures-a.exposures);}
